  <main id="main-content" class="page">
    <header class="hero">
      <p class="eyebrow">Support</p>
      <h1>Contact our support team</h1>
      <p class="intro">
        Send us your details and we will get back to you as soon as possible.
      </p>
    </header>

    <div class="layout">
      <section class="panel form-card" aria-labelledby="contact-form-heading">
        <h2 id="contact-form-heading">Send a message</h2>
        <p>Fields marked with <span class="required" aria-hidden="true">*</span> are required.</p>

        <form id="support-form" novalidate>
          <div class="form-field">
            <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
            <input
              id="full-name"
              name="fullName"
              type="text"
              autocomplete="name"
              required
              aria-describedby="full-name-error"
            >
            <p class="error-text" id="full-name-error" hidden>Please enter your full name.</p>
          </div>

          <div class="form-field">
            <label for="email-address">Email address <span class="required" aria-hidden="true">*</span></label>
            <input
              id="email-address"
              name="email"
              type="email"
              autocomplete="email"
              required
              aria-describedby="email-address-error"
            >
            <p class="error-text" id="email-address-error" hidden>Please enter a valid email address.</p>
          </div>

          <div class="form-field">
            <label for="phone-number">Phone number</label>
            <input
              id="phone-number"
              name="phone"
              type="tel"
              autocomplete="tel"
              inputmode="tel"
              aria-describedby="phone-number-help phone-number-error"
              placeholder="+1 555 123 4567"
            >
            <p class="help-text" id="phone-number-help">Use a format like +1 555 123 4567 or 555-123-4567.</p>
            <p class="error-text" id="phone-number-error" hidden>Please use the expected phone number format.</p>
          </div>

          <div class="actions">
            <button type="submit">Submit request</button>
            <p class="status" id="form-status" aria-live="polite"></p>
          </div>
        </form>
      </section>

      <aside class="panel aside" aria-label="What happens next">
        <h2>What happens next</h2>
        <p>After you submit, a support specialist will review your message and follow up by email.</p>
        <ul>
          <li>We reply to required details first.</li>
          <li>Phone is optional, but helpful for urgent issues.</li>
          <li>Your information is used only for support.</li>
        </ul>
      </aside>
    </div>
  </main>

  <script>
    const form = document.getElementById('support-form');
    const status = document.getElementById('form-status');
    const fields = [
      {
        input: document.getElementById('full-name'),
        error: document.getElementById('full-name-error'),
        validate: (value) => value.trim().length > 0
      },
      {
        input: document.getElementById('email-address'),
        error: document.getElementById('email-address-error'),
        validate: (value) => {
          if (!value.trim()) {
            return false;
          }

          return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());
        }
      },
      {
        input: document.getElementById('phone-number'),
        error: document.getElementById('phone-number-error'),
        validate: (value) => {
          const trimmed = value.trim();

          if (!trimmed) {
            return true;
          }

          return /^[+]?[\d\s().-]{7,}$/.test(trimmed);
        }
      }
    ];

    function setFieldState(field, isValid) {
      field.input.setAttribute('aria-invalid', String(!isValid));
      field.error.hidden = isValid;
    }

    function validateForm() {
      let firstInvalid = null;
      let hasErrors = false;

      fields.forEach((field) => {
        const isValid = field.validate(field.input.value);
        setFieldState(field, isValid);

        if (!isValid) {
          hasErrors = true;
          if (!firstInvalid) {
            firstInvalid = field.input;
          }
        }
      });

      return { hasErrors, firstInvalid };
    }

    form.addEventListener('submit', (event) => {
      event.preventDefault();
      status.textContent = '';

      const { hasErrors, firstInvalid } = validateForm();

      if (hasErrors) {
        status.textContent = 'Please correct the highlighted fields.';
        firstInvalid.focus();
        return;
      }

      status.textContent = 'Thanks — your request is ready to send.';
      form.reset();
      fields.forEach((field) => setFieldState(field, true));
      document.getElementById('full-name').focus();
    });

    fields.forEach((field) => {
      field.input.addEventListener('input', () => {
        if (field.input.getAttribute('aria-invalid') === 'true') {
          setFieldState(field, field.validate(field.input.value));
        }
      });
    });
  </script>
</body>
</html>
